package org.foldview.cctv

import android.content.Context
import android.content.Intent
import android.content.pm.PackageManager
import android.content.pm.SigningInfo
import android.os.Build
import android.net.Uri
import android.provider.Settings
import androidx.core.content.FileProvider
import java.io.File
import java.io.FileOutputStream
import java.net.HttpURLConnection
import java.net.URI
import java.security.MessageDigest
import java.util.Locale
import org.json.JSONObject

/** A LAN/HTTPS release manifest, generated by the administrator's GARDA OTA host. */
internal data class GardaRelease(
    val versionCode: Long,
    val versionName: String,
    val apkUrl: String,
    val sha256: String,
    val notes: String,
    val sizeBytes: Long
)

/**
 * Only downloads from the configured host. SHA256 confirms download integrity,
 * AND Android APK signing identity must match the already installed application.
 * Never installs silently: delegates to the Android package installer.
 */
internal object GardaUpdateClient {
    const val RELEASES_DRIVE_FOLDER =
        "https://drive.google.com/drive/folders/10CH9pSvjcSp7QoKv4nKdv2W5ePbHti9a"
    private const val LIMIT_BYTES: Long = 200L * 1024 * 1024
    private const val JSON_LIMIT = 16_384

    fun version(context: Context): Pair<String, Long> {
        val pkg = context.packageManager.getPackageInfo(context.packageName, 0)
        return (pkg.versionName ?: "unknown") to pkg.longVersionCode
    }

    /** Never use plain HTTP outside an RFC1918 address. HTTPS requires a valid certificate. */
    private fun validatedUrl(raw: String): URI {
        val uri = URI(raw.trim())
        require(uri.host != null && uri.userInfo == null && uri.fragment == null) {
            "Invalid OTA server address"
        }
        val scheme = uri.scheme?.lowercase(Locale.ROOT)
        require(scheme == "http" || scheme == "https") {
            "Only http://LAN-IP or HTTPS update servers are supported"
        }
        if (scheme == "http") {
            // Reject DNS hostnames for plain HTTP to avoid accidental cleartext internet downloads.
            require(Regex("(?:\\d{1,3}\\.){3}\\d{1,3}").matches(uri.host)) {
                "Unencrypted OTA requires a private LAN IPv4 address"
            }
            val ip = uri.host.split(".").map { it.toIntOrNull() ?: -1 }
            require(ip.size == 4 && ip.all { it in 0..255 } &&
                (ip[0] == 10 || (ip[0] == 172 && ip[1] in 16..31) ||
                    (ip[0] == 192 && ip[1] == 168))) {
                "HTTP updates are restricted to private LAN addresses"
            }
        }
        require(uri.port in -1..65535) { "Invalid OTA port" }
        return uri
    }

    private fun open(url: URI): HttpURLConnection {
        val connection = (url.toURL().openConnection() as HttpURLConnection)
        connection.instanceFollowRedirects = false
        connection.connectTimeout = 4_000
        connection.readTimeout = 10_000
        connection.setRequestProperty("Accept", "application/json, application/vnd.android.package-archive")
        connection.setRequestProperty("User-Agent", "GARDA-FOLD-OTA")
        return connection
    }

    fun check(context: Context, manifestUrl: String): GardaRelease {
        val origin = validatedUrl(manifestUrl)
        require(origin.rawPath?.endsWith("/manifest.json") == true) {
            "OTA server URL must end with /manifest.json"
        }
        val c = open(origin)
        val body: String
        try {
            check(c.responseCode == 200) { "Update server replied HTTP " + c.responseCode }
            if (c.contentLengthLong > JSON_LIMIT) error("Update manifest too large")
            body = c.inputStream.use { input ->
                val memory = java.io.ByteArrayOutputStream()
                val buffer = ByteArray(4096)
                while (true) {
                    val read = input.read(buffer)
                    if (read < 0) break
                    check(memory.size() + read <= JSON_LIMIT) { "Update manifest too large" }
                    memory.write(buffer, 0, read)
                }
                String(memory.toByteArray(), Charsets.UTF_8)
            }
        } finally {
            c.disconnect()
        }
        val json = JSONObject(body)
        require(json.getString("packageName") == context.packageName) {
            "Server release does not belong to GARDA CCTV FOLD edition"
        }
        val code = json.getLong("versionCode")
        val name = json.getString("versionName").take(48)
        val checksum = json.getString("sha256").lowercase(Locale.ROOT)
        val size = json.optLong("sizeBytes", 0)
        require(code > 0 && name.isNotBlank()) { "Invalid release version" }
        require(Regex("[0-9a-f]{64}").matches(checksum)) { "Release checksum must be SHA-256" }
        require(size in 1..LIMIT_BYTES) { "Invalid release APK size" }
        val apk = validatedUrl(json.getString("apkUrl"))
        // No third party redirect/hijack: a manifest can only name its own server.
        require(apk.scheme == origin.scheme && apk.host == origin.host &&
            apk.port == origin.port && apk.rawPath.endsWith(".apk")) {
            "APK URL must use the same trusted update server"
        }
        require(apk.query == null) { "Query parameters are not supported for OTA APK" }
        return GardaRelease(code, name, apk.toASCIIString(), checksum,
            json.optString("notes", "").take(900), size)
    }

    fun download(context: Context, release: GardaRelease, onProgress: (Int) -> Unit): File {
        val otaDir = File(context.cacheDir, "garda_ota").apply { mkdirs() }
        val part = File(otaDir, "GARDA-update.part.apk")
        val completed = File(otaDir, "GARDA-update.apk")
        part.delete()
        completed.delete()
        val u = validatedUrl(release.apkUrl)
        val c = open(u)
        val digest = MessageDigest.getInstance("SHA-256")
        var total = 0L
        try {
            check(c.responseCode == 200) { "APK server HTTP " + c.responseCode }
            check(c.contentType.orEmpty().lowercase(Locale.ROOT).let {
                !it.contains("text/html") && !it.contains("json")
            }) { "Server sent an HTML/login page, not an APK" }
            FileOutputStream(part).use { output ->
                c.inputStream.use { input ->
                    val buffer = ByteArray(65_536)
                    while (true) {
                        val count = input.read(buffer)
                        if (count < 0) break
                        total += count
                        check(total <= LIMIT_BYTES) { "APK exceeds maximum allowed size" }
                        digest.update(buffer, 0, count)
                        output.write(buffer, 0, count)
                        val percent = ((total * 100L) / release.sizeBytes).toInt().coerceIn(0, 99)
                        onProgress(percent)
                    }
                    output.fd.sync()
                }
            }
            check(total == release.sizeBytes) { "APK size differs from release manifest" }
            val computed = digest.digest().joinToString("") { "%02x".format(it) }
            check(computed == release.sha256) { "APK checksum mismatch" }
            verifyApk(context, part, release)
            check(part.renameTo(completed)) { "Could not finalize verified APK" }
            onProgress(100)
            return completed
        } catch (e: Exception) {
            part.delete()
            throw e
        } finally {
            c.disconnect()
        }
    }

    private fun verifyApk(context: Context, file: File, release: GardaRelease) {
        val pm = context.packageManager
        @Suppress("DEPRECATION")
        val installed = pm.getPackageInfo(context.packageName, PackageManager.GET_SIGNING_CERTIFICATES)
        @Suppress("DEPRECATION")
        val incoming = pm.getPackageArchiveInfo(file.absolutePath, PackageManager.GET_SIGNING_CERTIFICATES)
            ?: error("Downloaded file is not a valid Android APK")
        check(incoming.packageName == context.packageName) { "APK package ID mismatch" }
        check(incoming.longVersionCode == release.versionCode) { "APK version differs from manifest" }
        check(incoming.longVersionCode > installed.longVersionCode) { "Downloaded APK is not newer" }
        val previous = installed.signingInfo?.apkContentsSigners?.map { it.toCharsString() }?.toSet()
        val verifiedSigner = if (Build.VERSION.SDK_INT >= 36) {
            PackageManager.getVerifiedSigningInfo(
                file.absolutePath, SigningInfo.VERSION_SIGNING_BLOCK_V2
            )
        } else incoming.signingInfo
        val next = verifiedSigner?.apkContentsSigners?.map { it.toCharsString() }?.toSet()
        check(!previous.isNullOrEmpty() && previous == next) {
            "Signing certificate mismatch. The previous debug APK uses a different signing key." +
                " Back up profiles before any manual uninstall. OTA blocked."
        }
    }

    fun requestInstall(context: Context, apk: File) {
        check(apk.isFile && apk.length() > 0) { "Verified update APK is missing" }
        if (!context.packageManager.canRequestPackageInstalls()) {
            val intent = Intent(
                Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,
                Uri.parse("package:" + context.packageName)
            ).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)
            context.startActivity(intent)
            return
        }
        val uri = FileProvider.getUriForFile(
            context, context.packageName + ".ota.provider", apk
        )
        val install = Intent(Intent.ACTION_VIEW)
            .setDataAndType(uri, "application/vnd.android.package-archive")
            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_GRANT_READ_URI_PERMISSION)
        context.startActivity(install)
    }
}
